from vllm_ascend.ops.vocab_parallel_embedding import (
    VocabParallelEmbedding,
    ParallelLMHead,
)

# Temporal patch for EVS (Efficient Video Subsampling)
# This patch overrides the default embedding behavior
# to support multimodal pruning on Ascend NPU
def _patched_get_embedding_mask(self, input_ids):
    if self.is_multimodal_pruning_enabled:
        return self._evs_embedding_mask(input_ids)
    return self._original_embedding_mask(input_ids)

VocabParallelEmbedding._original_get_embedding_mask = (
    VocabParallelEmbedding.get_embedding_mask
)
VocabParallelEmbedding.get_embedding_mask = _patched_get_embedding_mask

